//! Vectors generated by running reference implementations (unmodified server
//! modules and nullspace's MIT checksum routine). See `vectors/README.md`.

use oss_proto::checksum::{position_checksum, settings_checksum, vie_exe_checksum};
use oss_proto::settings::{
    ARENA_BITS, BYTE_KEYS, LONG_KEYS, PRIZE_WEIGHT_KEYS, SHIP_BYTE_KEYS, SHIP_LONG_KEYS,
    SHIP_MISC_BITS, SHIP_NAMES, SHIP_SHORT_KEYS, SHIP_WEAPON_BITS, SHORT_KEYS,
};
use oss_proto::{C2SPosition, ClientSettings, Packet, S2CWeapon};

fn hex(s: &str) -> Vec<u8> {
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
        .collect()
}

fn records(text: &'static str) -> impl Iterator<Item = Vec<&'static str>> {
    text.lines()
        .filter(|l| !l.starts_with('#'))
        .map(|l| l.split_whitespace().collect())
}

#[test]
fn position_checksums() {
    let text = include_str!("vectors/position-checksum.txt");
    let (mut good, mut bad, mut s2c) = (0, 0, 0);
    for f in records(text) {
        let b = hex(f[1]);
        match f[0] {
            "c2s" => {
                assert_eq!(position_checksum(&b[..22]), 0);
                let p = C2SPosition::decode(&b).unwrap();
                assert!(p.checksum_ok(), "{}", f[1]);
                assert_eq!(p.to_bytes(), b, "re-encode computes the same checksum");
                good += 1;
            }
            "c2s_bad" => {
                assert!(!C2SPosition::decode(&b).unwrap().checksum_ok());
                bad += 1;
            }
            "s2c" => {
                let p = S2CWeapon::decode(&b).unwrap();
                assert!(p.checksum_ok(), "{}", f[1]);
                assert_eq!(p.to_bytes(), b);
                s2c += 1;
            }
            other => panic!("unknown record {other}"),
        }
    }
    assert_eq!((good, bad, s2c), (40, 8, 40));
}

#[test]
fn vie_exe_checksums() {
    let text = include_str!("vectors/vie-exe-checksum.txt");
    let mut n = 0;
    for f in records(text) {
        let key = u32::from_str_radix(f[1], 16).unwrap();
        let want = u32::from_str_radix(f[2], 16).unwrap();
        assert_eq!(vie_exe_checksum(key), want, "key {key:#x}");
        n += 1;
    }
    assert_eq!(n, 32);
}

/// (bit offset, bit length) of every named setting according to our tables.
/// Several names map to more than one place; all are listed.
fn layout() -> Vec<(String, u32, u32)> {
    let mut v = Vec::new();
    for (key, lo, w) in ARENA_BITS {
        v.push((key.to_string(), lo, w));
    }
    // The reference names two arena bits after its own override keys.
    v.push(("Misc:DisableBallThroughWalls".into(), 19, 1));
    v.push(("Misc:DisableBallKilling".into(), 20, 1));
    for (s, ship) in SHIP_NAMES.iter().enumerate() {
        let base = 32 + s as u32 * 144 * 8;
        for (i, k) in SHIP_LONG_KEYS.iter().enumerate() {
            v.push((format!("{ship}:{k}"), base + i as u32 * 32, 32));
        }
        for (i, k) in SHIP_SHORT_KEYS.iter().enumerate() {
            let k = if k.is_empty() {
                "___MiscBitfield___"
            } else {
                k
            };
            v.push((format!("{ship}:{k}"), base + 64 + i as u32 * 16, 16));
        }
        let misc = base + 64 + 10 * 16;
        for (k, lo, w) in SHIP_MISC_BITS {
            v.push((format!("{ship}:{k}"), misc + lo, w));
        }
        for (i, k) in SHIP_BYTE_KEYS.iter().enumerate() {
            v.push((format!("{ship}:{k}"), base + 64 + 49 * 16 + i as u32 * 8, 8));
        }
        let weapons = base + 64 + 49 * 16 + 18 * 8;
        for (k, lo, w) in SHIP_WEAPON_BITS {
            v.push((format!("{ship}:{k}"), weapons + lo, w));
        }
        v.push((format!("{ship}:Unused1"), weapons + 29, 3));
    }
    let longs = 32 + 8 * 144 * 8;
    for (i, k) in LONG_KEYS.iter().enumerate() {
        v.push((k.to_string(), longs + i as u32 * 32, 32));
    }
    let spawns = longs + 20 * 32;
    for t in 0..4u32 {
        for (name, lo, w) in [("X", 0, 10), ("Y", 10, 10), ("Radius", 20, 9)] {
            v.push((format!("Spawn:Team{t}-{name}"), spawns + t * 32 + lo, w));
        }
    }
    let shorts = spawns + 4 * 32;
    for (i, k) in SHORT_KEYS.iter().enumerate() {
        v.push((k.to_string(), shorts + i as u32 * 16, 16));
    }
    let bytes = shorts + 58 * 16;
    for (i, k) in BYTE_KEYS.iter().enumerate() {
        v.push((k.to_string(), bytes + i as u32 * 8, 8));
    }
    let weights = bytes + 32 * 8;
    for (i, k) in PRIZE_WEIGHT_KEYS.iter().enumerate() {
        v.push((k.to_string(), weights + i as u32 * 8, 8));
    }
    v
}

fn read_bits(b: &[u8], off: u32, len: u32) -> u64 {
    (0..len).fold(0u64, |acc, i| {
        let bit = off + i;
        acc | (u64::from(b[(bit / 8) as usize] >> (bit % 8) & 1) << i)
    })
}

fn check_settings(text: &'static str) {
    let mut packet = None;
    let mut fields = 0;
    let mut checksums = 0;
    let layout = layout();
    for f in records(text) {
        match f[0] {
            "size" => assert_eq!(f[1], "1428"),
            "packet" => {
                let b = hex(f[1]);
                let s = ClientSettings::decode(&b).unwrap();
                assert_eq!(s.to_bytes(), b, "settings re-encode exactly");
                packet = Some(b);
            }
            "checksum" => {
                let key = u32::from_str_radix(f[1], 16).unwrap();
                let want = u32::from_str_radix(f[2], 16).unwrap();
                assert_eq!(settings_checksum(key, packet.as_ref().unwrap()), want);
                checksums += 1;
            }
            "field" => {
                let (name, off, len): (&str, u32, u32) =
                    (f[1], f[2].parse().unwrap(), f[3].parse().unwrap());
                let value: i64 = f[4].parse().unwrap();
                assert!(
                    layout
                        .iter()
                        .any(|(n, o, l)| n == name && *o == off && *l == len),
                    "{name} at bit {off} (+{len}) is not in our tables"
                );
                let mask = if len == 64 {
                    u64::MAX
                } else {
                    (1u64 << len) - 1
                };
                let got = read_bits(packet.as_ref().unwrap(), off, len);
                assert_eq!(got, value as u64 & mask, "{name}");
                fields += 1;
            }
            other => panic!("unknown record {other}"),
        }
    }
    assert!(
        fields > 800 && checksums == 7,
        "{fields} fields, {checksums} checksums"
    );
}

#[test]
fn settings_default_zone() {
    check_settings(include_str!("vectors/clientset-asss-public.txt"));
}

#[test]
fn settings_subgame_defaults() {
    check_settings(include_str!("vectors/clientset-subgame-svs.txt"));
}

#[test]
fn settings_accessors_agree_with_reference_values() {
    let text = include_str!("vectors/clientset-asss-public.txt");
    let b = records(text)
        .find(|f| f[0] == "packet")
        .map(|f| hex(f[1]))
        .unwrap();
    let s = ClientSettings::decode(&b).unwrap();
    let field = |name: &str| -> i64 {
        records(text)
            .find(|f| f[0] == "field" && f[1] == name)
            .unwrap()[4]
            .parse()
            .unwrap()
    };
    let jav = &s.ships[1];
    assert_eq!(i64::from(jav.super_time()), field("Javelin:SuperTime"));
    assert_eq!(
        i64::from(jav.maximum_speed()),
        field("Javelin:MaximumSpeed")
    );
    assert_eq!(i64::from(jav.gravity()), field("Javelin:Gravity"));
    assert_eq!(i64::from(jav.max_guns()), field("Javelin:MaxGuns"));
    assert_eq!(i64::from(jav.shrapnel_max()), field("Javelin:ShrapnelMax"));
    assert_eq!(i64::from(jav.radius()), field("Javelin:Radius"));
    assert_eq!(i64::from(s.door_mode()), field("Door:DoorMode"));
    assert_eq!(
        i64::from(s.bullet_damage_level()),
        field("Bullet:BulletDamageLevel")
    );
    assert_eq!(i64::from(s.prize_weights[27]), field("PrizeWeight:Portal"));
    assert_eq!(
        i64::from(s.slow_frame_check()),
        field("Misc:SlowFrameCheck")
    );
}
